[{"id":"broken","age":18,"acceptedTerms":true}
EOF
cat > src/check.mjs <<'EOF'
import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

export function buildReport(rows) {
  if (!Array.isArray(rows)) throw new Error('input must be an array');
  const approved = [];
  const rejected = [];
  for (const row of rows) {
    const valid = row !== null
      && typeof row === 'object'
      && typeof row.id === 'string'
      && row.id.length > 0
      && Number.isInteger(row.age)
      && row.age >= 0
      && row.age <= 130
      && typeof row.acceptedTerms === 'boolean';
    if (!valid) throw new Error('invalid record');
    const eligible = row.age > 18 && row.acceptedTerms === true;
    (eligible ? approved : rejected).push(row.id);
  }
  return { approved, rejected };
}

function readInput(path) {
  const text = readFileSync(path, 'utf8');
  try {
    return JSON.parse(text);
  } catch (error) {
    if (error instanceof SyntaxError) throw new Error('malformed JSON');
    throw error;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    if (process.argv.length !== 3) throw new Error('usage: node src/check.mjs <input.json>');
    process.stdout.write(`${JSON.stringify(buildReport(readInput(process.argv[2])))}\n`);
  } catch (error) {
    process.stderr.write(`ERROR: ${error.message}\n`);
    process.exitCode = 2;
  }
}
EOF
