cat > test/immutable-contract.test.mjs <<'EOF'
import { readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { buildReport } from '../src/check.mjs';

const load = (name) => JSON.parse(readFileSync(`fixtures/${name}`, 'utf8'));
const cases = [
  {
    name: 'positive input',
    expected: { approved: ['boundary-adult'], rejected: [] },
    actual: () => buildReport(load('positive.json'))
  },
  {
    name: 'negative input',
    expected: { approved: [], rejected: ['minor', 'declined'] },
    actual: () => buildReport(load('negative.json'))
  },
  {
    name: 'changed input',
    expected: { approved: ['boundary-adult', 'new-boundary'], rejected: [] },
    actual: () => buildReport(load('changed.json'))
  },
  {
    name: 'malformed input',
    expected: { status: 2, stdout: '', stderr: 'ERROR: malformed JSON\n' },
    actual: () => {
      const result = spawnSync(process.execPath, ['src/check.mjs', 'fixtures/malformed.json'], { encoding: 'utf8' });
      return { status: result.status, stdout: result.stdout, stderr: result.stderr };
    }
  }
];

let passed = 0;
for (const item of cases) {
  const actual = item.actual();
  if (JSON.stringify(actual) === JSON.stringify(item.expected)) {
    passed += 1;
    console.log(`PASS ${item.name}`);
  } else {
    console.log(`FAIL ${item.name}`);
    console.log(`  expected: ${JSON.stringify(item.expected)}`);
    console.log(`  actual:   ${JSON.stringify(actual)}`);
  }
}
const failed = cases.length - passed;
console.log(`RESULT ${passed} passed, ${failed} failed`);
process.exitCode = failed === 0 ? 0 : 1;
EOF
